-- ─────────────────────────────────────────────────────────────
--  BOOTY FLOW APP — QUESTIONNAIRE ET PROGRAMMES PRÉCONÇUS (étape 3)
--  À lancer APRÈS supabase/formules.sql : Supabase › SQL Editor › New query › Run.
--  On peut le relancer sans risque (les brouillons ne sont ajoutés qu'une fois).
--
--  Organisation : programme → cycles de 12 semaines → 12 semaines (consigne de la semaine)
--                 → séances (A, B, C…, répétées chaque semaine) → exercices, avec pour chaque
--                 exercice la progression semaine par semaine (séries, répétitions, consigne de charge).
-- ─────────────────────────────────────────────────────────────

-- 1. Programmes
create table if not exists public.programmes_app (
  id uuid primary key default gen_random_uuid(),
  nom text not null,
  niveau text not null check (niveau in ('intermediaire', 'avancee')),
  seances_semaine int not null check (seances_semaine between 1 and 7),
  description text,
  ordre int not null default 0,
  actif boolean not null default true,
  created_at timestamptz not null default now()
);

-- 2. Cycles de 12 semaines. semaines = [{ numero, consigne }] (12 éléments)
create table if not exists public.cycles_app (
  id uuid primary key default gen_random_uuid(),
  programme_id uuid not null references public.programmes_app on delete cascade,
  numero int not null,
  titre text,
  description text,
  semaines jsonb not null default '[]',
  unique (programme_id, numero)
);

-- 3. Séances du cycle. exercices = [{ nom, principal, series, reps, repos, consignes,
--    video_id, progression: [{ series, reps, charge }] × 12 semaines }]
create table if not exists public.seances_app (
  id uuid primary key default gen_random_uuid(),
  cycle_id uuid not null references public.cycles_app on delete cascade,
  ordre int not null default 1,
  nom text not null,
  description text,
  exercices jsonb not null default '[]'
);
create index if not exists seances_app_cycle on public.seances_app (cycle_id, ordre);

-- 4. Réponses au questionnaire et programme attribué (une ligne par abonnée)
create table if not exists public.profils_app (
  eleve_id uuid primary key references public.profiles on delete cascade,
  age int check (age between 14 and 99),
  taille numeric check (taille between 120 and 220),
  poids_depart numeric check (poids_depart between 30 and 250),
  niveau text check (niveau in ('intermediaire', 'avancee')),
  seances_semaine int check (seances_semaine in (3, 4)),
  lieu text check (lieu in ('salle', 'maison')),
  objectif text check (objectif in ('perte_de_gras', 'prise_de_muscle')),
  programme_id uuid references public.programmes_app on delete set null,
  cycle_numero int not null default 1,
  debut_cycle date,
  complete_le timestamptz,
  updated_at timestamptz not null default now()
);

-- 5. Séances cochées (faite) ou passées (sautee), par cycle et par semaine
create table if not exists public.seances_faites (
  id uuid primary key default gen_random_uuid(),
  eleve_id uuid not null default auth.uid() references public.profiles on delete cascade,
  seance_id uuid not null references public.seances_app on delete cascade,
  cycle_numero int not null,
  semaine int not null check (semaine between 1 and 12),
  statut text not null default 'faite' check (statut in ('faite', 'sautee')),
  fait_le timestamptz not null default now(),
  unique (eleve_id, seance_id, cycle_numero, semaine)
);
create index if not exists seances_faites_eleve on public.seances_faites (eleve_id, cycle_numero);

-- ─── Sécurité ───
alter table public.programmes_app enable row level security;
alter table public.cycles_app enable row level security;
alter table public.seances_app enable row level security;
alter table public.profils_app enable row level security;
alter table public.seances_faites enable row level security;

-- Programmes : lisibles par les abonnées App (accès ouvert) ; modifiables par la coach seulement
drop policy if exists "programmes app lecture" on public.programmes_app;
create policy "programmes app lecture" on public.programmes_app for select using (public.est_coach() or public.acces_app());
drop policy if exists "programmes app coach" on public.programmes_app;
create policy "programmes app coach" on public.programmes_app for all using (public.est_coach()) with check (public.est_coach());
drop policy if exists "cycles app lecture" on public.cycles_app;
create policy "cycles app lecture" on public.cycles_app for select using (public.est_coach() or public.acces_app());
drop policy if exists "cycles app coach" on public.cycles_app;
create policy "cycles app coach" on public.cycles_app for all using (public.est_coach()) with check (public.est_coach());
drop policy if exists "seances app lecture" on public.seances_app;
create policy "seances app lecture" on public.seances_app for select using (public.est_coach() or public.acces_app());
drop policy if exists "seances app coach" on public.seances_app;
create policy "seances app coach" on public.seances_app for all using (public.est_coach()) with check (public.est_coach());

-- Questionnaire : l'abonnée lit le sien (elle l'écrit via terminer_questionnaire) ; la coach voit et modifie tout
drop policy if exists "profils app lecture" on public.profils_app;
create policy "profils app lecture" on public.profils_app for select using (public.est_coach() or eleve_id = auth.uid());
drop policy if exists "profils app coach" on public.profils_app;
create policy "profils app coach" on public.profils_app for all using (public.est_coach()) with check (public.est_coach());

-- Séances cochées : chaque abonnée gère les siennes (accès ouvert), la coach les voit
drop policy if exists "seances faites lecture" on public.seances_faites;
create policy "seances faites lecture" on public.seances_faites for select using (public.est_coach() or eleve_id = auth.uid());
drop policy if exists "seances faites ajout" on public.seances_faites;
create policy "seances faites ajout" on public.seances_faites for insert with check (eleve_id = auth.uid() and public.acces_app());
drop policy if exists "seances faites suppression" on public.seances_faites;
create policy "seances faites suppression" on public.seances_faites for delete using (eleve_id = auth.uid() and public.acces_app());

-- ─── Questionnaire de première connexion : enregistre les réponses et attribue le programme ───
create or replace function public.terminer_questionnaire(
  p_prenom text, p_age int, p_taille numeric, p_poids numeric,
  p_niveau text, p_seances int, p_lieu text, p_objectif text
) returns public.profils_app language plpgsql security definer set search_path = public as $$
declare
  prog uuid;
  ligne public.profils_app;
begin
  if not public.acces_app() then raise exception 'Réservé aux abonnées Booty Flow App'; end if;
  select id into prog from public.programmes_app
    where actif and niveau = p_niveau and seances_semaine = p_seances order by ordre limit 1;
  if nullif(trim(p_prenom), '') is not null then
    update public.profiles set prenom = left(trim(p_prenom), 60) where id = auth.uid();
  end if;
  insert into public.profils_app as pa (eleve_id, age, taille, poids_depart, niveau, seances_semaine, lieu, objectif,
                                        programme_id, cycle_numero, debut_cycle, complete_le, updated_at)
  values (auth.uid(), p_age, p_taille, p_poids, p_niveau, p_seances, p_lieu, p_objectif, prog, 1, current_date, now(), now())
  on conflict (eleve_id) do update set
    age = excluded.age, taille = excluded.taille, poids_depart = coalesce(pa.poids_depart, excluded.poids_depart),
    niveau = excluded.niveau, seances_semaine = excluded.seances_semaine, lieu = excluded.lieu, objectif = excluded.objectif,
    -- Nouveau programme seulement si le niveau ou le nombre de séances change (sinon on garde sa progression)
    programme_id = case when pa.programme_id is null or pa.niveau is distinct from excluded.niveau
                          or pa.seances_semaine is distinct from excluded.seances_semaine then excluded.programme_id else pa.programme_id end,
    cycle_numero = case when pa.programme_id is null or pa.niveau is distinct from excluded.niveau
                          or pa.seances_semaine is distinct from excluded.seances_semaine then 1 else pa.cycle_numero end,
    debut_cycle = coalesce(pa.debut_cycle, excluded.debut_cycle),
    complete_le = coalesce(pa.complete_le, now()), updated_at = now()
  returning * into ligne;
  return ligne;
end $$;

-- ─── Cycle suivant : seulement quand les 12 semaines du cycle en cours sont faites (ou passées) ───
create or replace function public.passer_cycle_suivant()
returns int language plpgsql security definer set search_path = public as $$
declare
  pa public.profils_app;
  cycle_actuel uuid;
  nb_seances int;
  nb_faites int;
begin
  if not public.acces_app() then raise exception 'Réservé aux abonnées Booty Flow App'; end if;
  select * into pa from public.profils_app where eleve_id = auth.uid();
  if pa.programme_id is null then raise exception 'Aucun programme attribué'; end if;
  select id into cycle_actuel from public.cycles_app where programme_id = pa.programme_id and numero = pa.cycle_numero;
  select count(*) into nb_seances from public.seances_app where cycle_id = cycle_actuel;
  select count(*) into nb_faites from public.seances_faites sf join public.seances_app s on s.id = sf.seance_id
    where sf.eleve_id = auth.uid() and sf.cycle_numero = pa.cycle_numero and s.cycle_id = cycle_actuel;
  if nb_seances = 0 or nb_faites < nb_seances * 12 then raise exception 'Le cycle en cours n''est pas terminé'; end if;
  if not exists (select 1 from public.cycles_app where programme_id = pa.programme_id and numero = pa.cycle_numero + 1) then
    raise exception 'Le cycle suivant n''est pas encore prêt';
  end if;
  update public.profils_app set cycle_numero = pa.cycle_numero + 1, debut_cycle = current_date, updated_at = now()
    where eleve_id = auth.uid();
  return pa.cycle_numero + 1;
end $$;

-- ─── Brouillons des 4 programmes ───
-- Brouillons des 4 programmes (créés seulement si aucun programme n'existe encore) :
-- 2 cycles de 12 semaines chacun, à modifier dans l'espace coach › Programmes App.
